package appcenter

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"errors"
	"io"
	"sync"

	"github.com/santhosh-tekuri/jsonschema/v6"
	"github.com/verdantflarehub/verdantflare-station-core/internal/strictjson"
)

var ErrInvalid = errors.New("APPCENTER_INVALID_FACTS")

// Generated by the design repository's scripts/contracts/generate_appcenter.py.
//
//go:embed schema.generated.json
var schemaBundle []byte

var schemas = sync.OnceValues(func() (map[string]*jsonschema.Schema, error) {
	var bundle map[string]any
	if err := json.Unmarshal(schemaBundle, &bundle); err != nil {
		return nil, err
	}
	c := jsonschema.NewCompiler()
	c.AssertFormat()
	for id, resource := range bundle {
		if err := c.AddResource(id, resource); err != nil {
			return nil, err
		}
	}
	result := map[string]*jsonschema.Schema{}
	for _, name := range []string{"command-core", "command-registry", "legacy"} {
		s, err := c.Compile("station://contracts/appcenter-v1/" + name)
		if err != nil {
			return nil, err
		}
		result[name] = s
	}
	return result, nil
})

// Decode permits contract-defined nulls while rejecting duplicate keys,
// unknown/absent fields and invalid values before typed decoding.
func Decode(r io.Reader, name string, limit int64, out any) error {
	raw, err := strictjson.ReadValue(r, limit)
	if err != nil {
		return ErrInvalid
	}
	all, err := schemas()
	if err != nil {
		return ErrInvalid
	}
	schema, ok := all[name]
	if !ok {
		return ErrInvalid
	}
	d := json.NewDecoder(bytes.NewReader(raw))
	d.UseNumber()
	var value any
	if d.Decode(&value) != nil || schema.Validate(value) != nil || json.Unmarshal(raw, out) != nil {
		return ErrInvalid
	}
	return nil
}
